1	// Neatlogs tracing setup. Plain TypeScript: no Next.js imports.
2	
3	import { flush, init, shutdown } from "neatlogs";
4	
5	let initialised = false;
6	
7	// Safe to call many times; only the first call initialises the SDK.
8	export async function initTracing(): Promise<void> {
9	  if (initialised) return;
10	  initialised = true;
11	  await init({
12	    apiKey: process.env.NEATLOGS_API_KEY,
13	    workflowName: "signalscout",
14	  });
15	}
16	
17	// For scripts only: push pending spans out, then shut the SDK down.
18	export async function closeTracing(): Promise<void> {
19	  await flush();
20	  await shutdown();
21	  initialised = false;
22	}
