1	import { describe, expect, it } from "vitest";
2	import { FixtureProvider } from "../src/core/data/fixture-provider";
3	import { BudgetGuard } from "../src/core/data/provider";
4	import { FIXTURE_COMPANIES } from "../src/core/fixtures/companies";
5	
6	const open = { country: "", industries: [], employee_count_ranges: [] };
7	
8	function make(max_search_results = 100, max_enrichments = 15, extra = {}) {
9	  return new FixtureProvider({ config: { max_search_results, max_enrichments }, ...extra });
10	}
11	
12	describe("BudgetGuard", () => {
13	  it("refuses calls that would exceed a cap", () => {
14	    const g = new BudgetGuard({ max_search_results: 5, max_enrichments: 2 });
15	    expect(g.canSearch(5)).toBe(true);
16	    expect(g.canSearch(6)).toBe(false);
17	    g.recordSearch(3, 0.1);
18	    expect(g.canSearch(3)).toBe(false);
19	    g.recordEnrich(2, 0.2);
20	    expect(g.canEnrich(1)).toBe(false);
21	    expect(g.snapshot()).toEqual({ cost_usd: expect.closeTo(0.3), searched: 3, enriched: 2 });
22	  });
23	});
24	
25	describe("FixtureProvider caps", () => {
26	  it("returns budget_cap_reached without making the call", async () => {
27	    const p = make(3, 1);
28	    const first = await p.searchCompanies(open, 3);
29	    expect(first.ok && first.data.length).toBe(3);
30	    const second = await p.searchCompanies(open, 1);
31	    expect(!second.ok && second.error.category).toBe("budget_cap_reached");
32	    const urls = FIXTURE_COMPANIES.slice(0, 2).map((c) => c.professional_network_url);
33	    const enrich = await p.enrichCompanies(urls);
34	    expect(!enrich.ok && enrich.error.category).toBe("budget_cap_reached");
35	    expect(p.calls_made).toBe(1);
36	  });
37	
38	  it("tracks simulated cost", async () => {
39	    const p = make(100, 15, { cost_usd: 0.5 });
40	    const r = await p.searchCompanies(open, 2);
41	    expect(r.ok && r.cost_usd).toBe(0.5);
42	    expect(p.budget.snapshot()).toEqual({ cost_usd: 0.5, searched: 2, enriched: 0 });
43	  });
44	
45	  it("costs nothing by default", async () => {
46	    const r = await make().searchCompanies(open, 2);
47	    expect(r.ok && r.cost_usd).toBe(0);
48	  });
49	});
50	
51	describe("FixtureProvider failure injection", () => {
52	  it("fails only the Nth call, then recovers", async () => {
53	    const p = make(100, 15, { failures: [{ call_number: 2, category: "rate_limited" }] });
54	    expect((await p.searchCompanies(open, 2)).ok).toBe(true);
55	    const failed = await p.searchCompanies(open, 2);
56	    expect(!failed.ok && failed.error.category).toBe("rate_limited");
57	    expect((await p.searchCompanies(open, 2)).ok).toBe(true);
58	    // The failed call spent nothing.
59	    expect(p.budget.snapshot().searched).toBe(4);
60	  });
61	});
62	
63	describe("FixtureProvider enrich", () => {
64	  it("returns matching records, tolerant of URL formatting", async () => {
65	    const target = FIXTURE_COMPANIES[0];
66	    const url = target.professional_network_url.toUpperCase() + "/";
67	    const r = await make().enrichCompanies([url]);
68	    expect(r.ok && r.data.map((c) => c.crustdata_company_id)).toEqual([target.crustdata_company_id]);
69	  });
70	
71	  it("returns no_match for unknown URLs", async () => {
72	    const r = await make().enrichCompanies(["https://www.linkedin.com/company/does-not-exist"]);
73	    expect(!r.ok && r.error.category).toBe("no_match");
74	  });
75	
76	  it("omits unknown URLs from a partial match", async () => {
77	    const known = FIXTURE_COMPANIES[0].professional_network_url;
78	    const r = await make().enrichCompanies([known, "https://www.linkedin.com/company/nope"]);
79	    expect(r.ok && r.data.length).toBe(1);
80	  });
81	});
82	
83	describe("FixtureProvider autocomplete", () => {
84	  it("matches industries and reports no_match", async () => {
85	    const p = make();
86	    const hit = await p.autocompleteIndustry("soft");
87	    expect(hit.ok && hit.data).toContain("Software");
88	    const miss = await p.autocompleteIndustry("zzz");
89	    expect(!miss.ok && miss.error.category).toBe("no_match");
90	  });
91	});
