1	// SignalScout core types. Plain TypeScript only: no Next.js imports.
2	// Data flows through four layers: Raw -> Validation -> Assessment -> Run.
3	
4	// ---------------------------------------------------------------------------
5	// Layer 1: RawCompany (what Crustdata returned, never edited)
6	// ---------------------------------------------------------------------------
7	
8	// Which Crustdata endpoint produced the data: "search" is the cheap list
9	// lookup, "enrich" is the paid, detailed lookup for one company.
10	export type SourceEndpoint = "search" | "enrich";
11	
12	// Fields every search result carries. Any text field may be an empty string
13	// when Crustdata has no value for it.
14	export interface RawSearchFields {
15	  // Crustdata's own numeric ID for the company. Our unique key.
16	  readonly crustdata_company_id: number;
17	  // Company name as Crustdata reports it.
18	  readonly name: string;
19	  // Main web domain, e.g. "acme.com". Different companies can share one.
20	  readonly primary_domain: string;
21	  // Company website URL as listed.
22	  readonly website: string;
23	  // The company's LinkedIn page URL.
24	  readonly professional_network_url: string;
25	  // Headcount bucket as text, e.g. "51-200".
26	  readonly employee_count_range: string;
27	  // Industry label as Crustdata reports it.
28	  readonly industry: string;
29	  // URL of the company logo image.
30	  readonly logo: string;
31	}
32	
33	// City / state / country of the company. Each part may be missing.
34	export interface RawLocation {
35	  // City name.
36	  readonly city?: string;
37	  // State or region.
38	  readonly state?: string;
39	  // Country name.
40	  readonly country?: string;
41	}
42	
43	// Extra fields only the enrich endpoint returns. All are optional because
44	// enrichment can come back partial.
45	export interface RawEnrichmentFields {
46	  // Free-text company description.
47	  readonly description?: string;
48	  // Year the company was founded.
49	  readonly founded_year?: number;
50	  // Legal structure, e.g. "Privately Held".
51	  readonly legal_type?: string;
52	  // Most recent total employee count.
53	  readonly latest_headcount?: number;
54	  // Revenue bucket as text, e.g. "$10M-$50M".
55	  readonly revenue_range?: string;
56	  // Where the company is based.
57	  readonly location?: RawLocation;
58	  // Topics / skills the company lists about itself.
59	  readonly specialities?: readonly string[];
60	  // Number of LinkedIn followers.
61	  readonly linkedin_followers?: number;
62	}
63	
64	// A company exactly as Crustdata gave it, plus bookkeeping about the call.
65	// Enrichment fields are absent for companies that were only searched.
66	export interface RawCompany extends RawSearchFields, RawEnrichmentFields {
67	  // Which endpoint this data came from.
68	  readonly source: SourceEndpoint;
69	  // When we received it, as an ISO 8601 timestamp.
70	  readonly retrieved_at: string;
71	  // What this one call cost in US dollars.
72	  readonly cost_usd: number;
73	}
74	
75	// ---------------------------------------------------------------------------
76	// Layer 2: Validation (decided by code rules, never by the model)
77	// ---------------------------------------------------------------------------
78	
79	// Overall verdict: "valid" = good to use, "flagged" = usable but suspicious,
80	// "rejected" = dropped from results.
81	export type ValidationStatus = "valid" | "flagged" | "rejected";
82	
83	// Machine-readable name of each rule that can fail.
84	export type ValidationIssueCode =
85	  | "missing_name" // no company name
86	  | "missing_domain" // no primary domain
87	  | "junk_website" // website is a placeholder or not a real site
88	  | "duplicate_domain" // another company in this run has the same domain (or LinkedIn URL)
89	  | "size_headcount_mismatch" // size bucket and headcount disagree
90	  | "missing_linkedin"; // no LinkedIn page
91	
92	// One problem found by a validation rule.
93	export interface ValidationIssue {
94	  // Which rule failed.
95	  readonly code: ValidationIssueCode;
96	  // The raw field the rule looked at, e.g. "primary_domain".
97	  readonly field: string;
98	  // Plain-English explanation of the problem.
99	  readonly reason: string;
100	  // For duplicate issues: the crustdata_company_id of the other record this
101	  // one appears to duplicate. Unused for other issue codes.
102	  readonly related_company_id?: number;
103	}
104	
105	// Result of running all code rules on one company.
106	export interface Validation {
107	  // The overall verdict.
108	  readonly status: ValidationStatus;
109	  // Every problem found. Empty when the company is clean.
110	  readonly issues: readonly ValidationIssue[];
111	}
112	
113	// ---------------------------------------------------------------------------
114	// Layer 3: Facts and Assessment (model-written judgement, grounded in facts)
115	// ---------------------------------------------------------------------------
116	
117	// How much we trust a fact. Only deterministic code ever sets this; the model
118	// may only reference existing fact ids and never assigns or changes a status.
119	// "given" = reported directly by a provider or the user, unchanged.
120	// "extracted" = pulled out of free text; not citeable until verified.
121	// "cross_checked" = at least two independent facts agree, and those facts are
122	//   listed in derived_from.
123	// "uncertain" = conflicting or unsupported; never citeable.
124	export type FactStatus = "given" | "extracted" | "cross_checked" | "uncertain";
125	
126	// Who produced a fact. Facts with provider "model" are never citeable.
127	export type FactProvider =
128	  | "crustdata"
129	  | "fixture"
130	  | "user_input"
131	  | "derived"
132	  | "model";
133	
134	// Where a fact came from.
135	export interface FactSource {
136	  // The system that produced the fact.
137	  readonly provider: FactProvider;
138	  // Which Crustdata operation returned it, when the provider is crustdata.
139	  readonly operation?: "autocomplete" | "company_search" | "company_enrich";
140	  // The provider's own ID for the record the fact came from.
141	  readonly record_id?: string;
142	  // When we received it, as an ISO 8601 timestamp.
143	  readonly retrieved_at: string;
144	  // Public URL backing the fact, if any.
145	  readonly source_url?: string;
146	}
147	
148	// One factual claim with its value, origin and trust level.
149	export interface Fact<T> {
150	  // Unique ID that scores and outreach drafts reference.
151	  readonly id: string;
152	  // The machine-readable value, e.g. 120.
153	  readonly value: T;
154	  // The claim in plain English, e.g. "Has about 120 employees".
155	  readonly claim: string;
156	  // The raw field this fact rests on, e.g. "latest_headcount".
157	  readonly field?: string;
158	  // Where the fact came from.
159	  readonly source: FactSource;
160	  // How trustworthy the fact is. Set by deterministic code only.
161	  readonly status: FactStatus;
162	  // When the fact was true, as an ISO 8601 timestamp, if known.
163	  readonly as_of?: string;
164	  // For "cross_checked" facts: IDs of the facts that agree.
165	  readonly derived_from?: readonly string[];
166	}
167	
168	// A fact of any value type.
169	export type AnyFact = Fact<unknown>;
170	
171	// Only facts with one of these statuses may be cited in outreach.
172	export const CITEABLE_FACT_STATUSES: readonly FactStatus[] = [
173	  "given",
174	  "cross_checked",
175	];
176	
177	// A score for one criterion from the user's request (e.g. "right size").
178	export interface CriterionScore {
179	  // Name of the criterion.
180	  readonly criterion: string;
181	  // Score from 0 (no match) to 100 (perfect match).
182	  readonly score: number;
183	  // Fact IDs backing this score.
184	  readonly fact_ids: readonly string[];
185	}
186	
187	// A draft first message to the company.
188	// Rule: it may only cite facts whose status is in CITEABLE_FACT_STATUSES
189	// and whose provider is not "model".
190	export interface OutreachDraft {
191	  // The message text.
192	  readonly body: string;
193	  // IDs of the facts the message relies on.
194	  readonly cited_fact_ids: readonly string[];
195	}
196	
197	// The model's overall view of how well a company fits the request.
198	export interface Assessment {
199	  // Overall fit from 0 (poor) to 100 (excellent).
200	  readonly fit_score: number;
201	  // Score for each criterion.
202	  readonly criterion_scores: readonly CriterionScore[];
203	  // Things the model could not confirm or is unsure about.
204	  readonly uncertainty_notes: readonly string[];
205	  // Optional first-contact message. Absent if no citeable fact exists.
206	  readonly outreach?: OutreachDraft;
207	}
208	
209	// ---------------------------------------------------------------------------
210	// Prospect: the three company layers together
211	// ---------------------------------------------------------------------------
212	
213	// One company moving through the pipeline. Assessment is added only after
214	// the company passes validation and gets enriched.
215	// Identity is raw.crustdata_company_id. Duplicate DETECTION is separate: it
216	// compares the normalised domain (lowercase, no protocol, no www, no trailing
217	// slash), falling back to the normalised LinkedIn URL when the domain is
218	// empty. A match raises a duplicate_domain issue (with related_company_id)
219	// and the earlier or cheaper record is kept. Two different Crustdata ids
220	// sharing a domain are a probable duplicate, not proof of identity.
221	export interface Prospect {
222	  // Untouched Crustdata data.
223	  readonly raw: RawCompany;
224	  // Code-rule verdict.
225	  readonly validation: Validation;
226	  // Every fact known about this company, each with a trust level.
227	  readonly facts: readonly AnyFact[];
228	  // Model judgement, if one was made.
229	  readonly assessment?: Assessment;
230	}
231	
232	// ---------------------------------------------------------------------------
233	// Layer 4: Run (one end-to-end execution of the agent)
234	// ---------------------------------------------------------------------------
235	
236	// Hard limits that keep a run from costing too much.
237	export interface RunConfig {
238	  // Most companies to pull from search. Default 100.
239	  readonly max_search_results: number;
240	  // Most companies to send to paid enrichment. Default 15.
241	  readonly max_enrichments: number;
242	  // Model used for planning and assessment.
243	  readonly model: string;
244	  // Most LLM calls allowed in one run.
245	  readonly max_llm_calls_per_run: number;
246	  // Most output tokens allowed in one LLM call.
247	  readonly max_output_tokens_per_call: number;
248	}
249	
250	// Default limits used when the caller sets none. The model and LLM caps are
251	// starting values to tune.
252	export const DEFAULT_RUN_CONFIG: RunConfig = {
253	  max_search_results: 100,
254	  max_enrichments: 15,
255	  model: "claude-haiku",
256	  max_llm_calls_per_run: 20,
257	  max_output_tokens_per_call: 1500,
258	};
259	
260	// Smaller limits for development runs, to keep Crustdata spend low.
261	export const DEV_RUN_CONFIG: RunConfig = {
262	  max_search_results: 10,
263	  max_enrichments: 2,
264	  model: "claude-haiku",
265	  max_llm_calls_per_run: 20,
266	  max_output_tokens_per_call: 1500,
267	};
268	
269	// How many companies reached each stage.
270	export interface RunCounts {
271	  // Companies returned by search.
272	  readonly searched: number;
273	  // Companies that were enriched.
274	  readonly enriched: number;
275	  // Companies in the final results.
276	  readonly delivered: number;
277	  // LLM calls made.
278	  readonly llm_calls: number;
279	  // Input tokens sent across all LLM calls.
280	  readonly llm_input_tokens: number;
281	  // Output tokens received across all LLM calls.
282	  readonly llm_output_tokens: number;
283	}
284	
285	// Pipeline step names, used for cost and timing breakdowns.
286	export type RunStep = "plan" | "search" | "validate" | "enrich" | "assess";
287	
288	// Dollars spent in each step.
289	export type RunCosts = Readonly<Record<RunStep, number>>;
290	
291	// Milliseconds spent in each step.
292	export type RunTimings = Readonly<Record<RunStep, number>>;
293	
294	// Record of one agent run.
295	export interface Run {
296	  // Unique ID that ties logs and traces to this run.
297	  readonly trace_id: string;
298	  // The user's plain-language description of who they want to find.
299	  readonly input_description: string;
300	  // Limits this run used.
301	  readonly config: RunConfig;
302	  // Stage-by-stage company counts.
303	  readonly counts: RunCounts;
304	  // US dollars spent per step.
305	  readonly cost_usd_by_step: RunCosts;
306	  // Milliseconds spent per step.
307	  readonly timings_ms_by_step: RunTimings;
308	}
309

