1	// Builds the real model client: an OpenAI SDK client pointed at the LiteLLM
2	// gateway, instrumented with neatlogs' wrapOpenAI, inside the agent's retry
3	// and cost-accounting adapter.
4	//
5	// Everything is passed in explicitly: this module never reads process.env,
6	// never initialises or closes tracing (entry points call initTracing() /
7	// closeTracing() from src/core/observability/tracing.ts), and never puts the
8	// API key in an error message.
9	
10	import { wrapOpenAI } from "neatlogs/openai";
11	import OpenAI from "openai";
12	import { LITELLM_GATEWAY_BASE_URL, LLM_REQUEST_TIMEOUT_MS } from "./llm-policy";
13	import {
14	  type LlmRetryPolicy,
15	  OpenAiCompatibleLlmClient,
16	  ResponseHeaderRecorder,
17	} from "./openai-llm";
18	
19	type Fetch = (input: string | URL | Request, init?: RequestInit) => Promise<Response>;
20	
21	export interface GatewayClientOptions {
22	  // Supplied by the entry point. Never logged.
23	  readonly apiKey: string;
24	  // Defaults to the shared LiteLLM gateway.
25	  readonly baseURL?: string;
26	  // Per HTTP attempt. Defaults to LLM_REQUEST_TIMEOUT_MS (30 s).
27	  readonly timeoutMs?: number;
28	  // Transport override, for tests. Defaults to the global fetch.
29	  readonly fetch?: Fetch;
30	}
31	
32	export interface GatewayLlmClientOptions extends GatewayClientOptions {
33	  readonly policy?: Partial<Omit<LlmRetryPolicy, "request_timeout_ms">>;
34	  readonly sleep?: (ms: number) => Promise<void>;
35	  readonly now?: () => number;
36	  readonly wall_clock?: () => number;
37	}
38	
39	export interface GatewayClient {
40	  // The wrapOpenAI-instrumented SDK client.
41	  readonly client: OpenAI;
42	  // Response headers recorded by the client's fetch.
43	  readonly headers: ResponseHeaderRecorder;
44	}
45	
46	export function createGatewayOpenAIClient(options: GatewayClientOptions): GatewayClient {
47	  if (typeof options.apiKey !== "string" || options.apiKey.trim() === "") {
48	    throw new Error("The model gateway API key is missing.");
49	  }
50	  const headers = new ResponseHeaderRecorder();
51	  const baseFetch: Fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
52	  const recordingFetch: Fetch = async (input, init) => {
53	    const response = await baseFetch(input, init);
54	    headers.record(response.headers);
55	    return response;
56	  };
57	  const sdk = new OpenAI({
58	    apiKey: options.apiKey,
59	    baseURL: options.baseURL ?? LITELLM_GATEWAY_BASE_URL,
60	    timeout: options.timeoutMs ?? LLM_REQUEST_TIMEOUT_MS,
61	    // Our adapter owns retries; the SDK default (2) would add hidden requests.
62	    maxRetries: 0,
63	    fetch: recordingFetch,
64	    // Explicit, so the SDK does not fall back to OPENAI_* environment values.
65	    organization: null,
66	    project: null,
67	    webhookSecret: null,
68	    logLevel: "warn",
69	  });
70	  return { client: wrapOpenAI(sdk), headers };
71	}
72	
73	export function createGatewayLlmClient(options: GatewayLlmClientOptions): OpenAiCompatibleLlmClient {
74	  const { client, headers } = createGatewayOpenAIClient(options);
75	  return new OpenAiCompatibleLlmClient({
76	    client,
77	    headers,
78	    records_llm_spans: true,
79	    policy: {
80	      ...options.policy,
81	      request_timeout_ms: options.timeoutMs ?? LLM_REQUEST_TIMEOUT_MS,
82	    },
83	    secrets: [options.apiKey],
84	    sleep: options.sleep,
85	    now: options.now,
86	    wall_clock: options.wall_clock,
87	  });
88	}
