1	// Adapts PipelineTracer to the neatlogs SDK. Entry points must call
2	// initTracing() from src/core/observability/tracing.ts first (and
3	// closeTracing() in scripts); without it neatlogs records nothing.
4	
5	import { trace } from "neatlogs";
6	import type {
7	  PipelineSpan,
8	  PipelineTracer,
9	  TraceAttributes,
10	} from "./tracer";
11	
12	type OtelSpan = Parameters<Parameters<typeof trace>[1]>[0];
13	type OtelAttributes = Parameters<OtelSpan["setAttributes"]>[0];
14	
15	// OpenTelemetry attribute arrays are mutable; copy readonly arrays.
16	function toOtelAttributes(attributes: TraceAttributes): OtelAttributes {
17	  const out: OtelAttributes = {};
18	  for (const [key, value] of Object.entries(attributes)) {
19	    if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
20	      out[key] = value;
21	    } else {
22	      out[key] = [...value] as string[] | number[];
23	    }
24	  }
25	  return out;
26	}
27	
28	export const neatlogsTracer: PipelineTracer = {
29	  span(options, fn) {
30	    return trace(
31	      { name: options.name, kind: options.kind, input: options.input },
32	      async (otelSpan) => {
