1	// Fake SignalScout pipeline that only exists to produce a Neatlogs trace.
2	// Uses the synthetic fixtures: no network calls except the Neatlogs export,
3	// and no model calls. Run: npx tsx scripts/hello-trace.ts
4	
5	import { span, trace } from "neatlogs";
6	import { FixtureProvider } from "../src/core/data/fixture-provider";
7	import { validateCompanies } from "../src/core/data/validation";
8	import { closeTracing, initTracing } from "../src/core/observability/tracing";
9	import { DEV_RUN_CONFIG, type RawCompany, type Validation } from "../src/core/types";
10	
11	const provider = new FixtureProvider({ config: DEV_RUN_CONFIG });
12	
13	const search = span({ kind: "TOOL", name: "search" }, async () => {
14	  const result = await provider.searchCompanies(
15	    { country: "", industries: [], employee_count_ranges: [] },
16	    DEV_RUN_CONFIG.max_search_results,
17	  );
18	  if (!result.ok) throw new Error(`search failed: ${result.error.category}`);
19	  return result.data;
20	});
21	
22	const validate = span(
23	  { kind: "GUARDRAIL", name: "validate" },
24	  async (companies: readonly RawCompany[]) =>
25	    trace({ name: "validate_companies", kind: "GUARDRAIL" }, async (activeSpan) => {
26	      const validations = validateCompanies(companies);
27	      const count = (status: Validation["status"]) =>
28	        validations.filter((v) => v.status === status).length;
29	      const issueCodes = [
30	        ...new Set(validations.flatMap((v) => v.issues.map((i) => i.code))),
31	      ].sort();
32	      activeSpan.setAttribute("validation.valid_count", count("valid"));
33	      activeSpan.setAttribute("validation.flagged_count", count("flagged"));
34	      activeSpan.setAttribute("validation.rejected_count", count("rejected"));
35	      activeSpan.setAttribute("validation.issue_codes", issueCodes);
36	      return validations;
37	    }),
38	);
39	
40	const enrich = span(
41	  { kind: "TOOL", name: "enrich" },
42	  async (companies: readonly RawCompany[]) => {
43	    const urls = companies
44	      .map((c) => c.professional_network_url)
45	      .filter((u) => u !== "")
46	      .slice(0, DEV_RUN_CONFIG.max_enrichments);
47	    const result = await provider.enrichCompanies(urls);
48	    if (!result.ok) throw new Error(`enrich failed: ${result.error.category}`);
49	    return result.data;
50	  },
51	);
52	
53	// Stubbed: no model call. Gives every company the same placeholder score.
54	const score = span(
55	  { kind: "AGENT", name: "score" },
56	  async (companies: readonly RawCompany[]) =>
57	    companies.map((c) => ({ crustdata_company_id: c.crustdata_company_id, score: 0 })),
58	);
59	
60	const run = span({ kind: "WORKFLOW", name: "signalscout_run" }, async () => {
61	  const found = await search();
62	  const validations = await validate(found);
63	  // Only records that survived validation go on to paid enrichment.
64	  const usable = found.filter((_, i) => validations[i].status !== "rejected");
65	  const enriched = await enrich(usable);
66	  const scores = await score(enriched);
67	  return {
68	    searched: found.length,
69	    usable: usable.length,
70	    enriched: enriched.length,
71	    scored: scores.length,
72	  };
73	});
74	
75	async function main(): Promise<void> {
76	  await initTracing();
77	  try {
78	    const summary = await run();
79	    console.log("hello-trace done:", summary);
80	  } finally {
81	    await closeTracing();
82	  }
83	}
84	
85	main().catch((err) => {
86	  console.error(err instanceof Error ? err.message : err);
87	  process.exitCode = 1;
88	});
